jstrain/quiz-06-classes-prototypes/q02.snippet:
class Animal {
  speak() {
    return 'generic';
  }
}
class Dog extends Animal {
  speak() {
    return 'woof (' + super.speak() + ')';
  }
}
const d = new Dog();
console.log(d.speak());
console.log(d instanceof Dog, d instanceof Animal, d instanceof Object);

jstrain/quiz-06-classes-prototypes/q03.snippet:
class Rect {
  constructor(w, h) {
    this.w = w;
    this.h = h;
  }
  get area() {
    return this.w * this.h;
  }
  toString() {
    return `Rect(${this.w}x${this.h})`;
  }
}
const r = new Rect(2, 3);
console.log(r.area);
console.log(`${r}`);
console.log(String(r), r + '');
console.log(Object.keys(r));

jstrain/quiz-06-classes-prototypes/q04.snippet:
