jstrain/quiz-06-classes-prototypes/q09.snippet:
class Handler {
  label = 'H';
  method() {
    return this.label;
  }
  arrow = () => this.label;
}
const h = new Handler();
const m = h.method;
const ar = h.arrow;
console.log(h.method(), h.arrow());
try {
  console.log(m());
} catch (e) {
  console.log('method detached:', e.constructor.name);
}
console.log('arrow detached:', ar());
