jstrain/quiz-06-classes-prototypes/q10.snippet:
class Account {
  #balance = 0;
  deposit(n) {
    this.#balance += n;
    return this;
  }
  get balance() {
    return this.#balance;
  }
  set balance(v) {
    throw new Error('read only');
  }
}
